<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import client from '../api/client'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'
const router=useRouter(),data=ref<any>({states:{},latest_monitors:[],recent_incidents:[],probe_stats_24h:{}}),error=ref(''),loading=ref(false),refreshSeconds=ref(30),lastUpdated=ref(''),live=ref(false)
let timer:number|undefined,socket:WebSocket|undefined,reconnectTimer:number|undefined,reloadTimer:number|undefined,stopped=false,requestVersion=0
const stateText:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',MAINTENANCE:'维护',PAUSED:'暂停',PENDING:'待探测',UNKNOWN:'未知'}
const stateClass=(s:string)=>s?.toLowerCase()||'unknown'
const totalStates=computed(()=>Object.values(data.value.states||{}).reduce((a:number,b:any)=>a+Number(b),0))
const healthyRate=computed(()=>data.value.health_rate==null?0:Number(data.value.health_rate))
const businessRows=computed(()=>{const map:any={};for(const m of data.value.latest_monitors||[]){const item=map[m.business]||(map[m.business]={name:m.business,total:0,up:0,down:0,degraded:0,last:null});item.total++;if(m.status==='UP')item.up++;if(m.status==='DOWN')item.down++;if(m.status==='DEGRADED')item.degraded++;if(!item.last||m.last_checked_at>item.last)item.last=m.last_checked_at}return (Object.values(map) as any[]).sort((a:any,b:any)=>(b.down+b.degraded)-(a.down+a.degraded))})
const attention=computed(()=>(data.value.latest_monitors||[]).filter((m:any)=>m.available===false||['DOWN','DEGRADED','PENDING'].includes(m.status)).slice(0,8))
const fmt=(v:any)=>v?new Date(v).toLocaleString():'—'
async function load(){if(stopped)return;const version=++requestVersion;loading.value=true;try{const response=await client.get('/dashboard/summary/');if(stopped||version!==requestVersion)return;data.value=response.data;lastUpdated.value=new Date(response.data.snapshot_at||Date.now()).toLocaleTimeString();error.value=''}catch(e:any){if(!stopped&&version===requestVersion)error.value=e.response?.data?.message||e.message||'总览加载失败'}finally{if(version===requestVersion)loading.value=false}}
function scheduleLoad(){if(stopped||reloadTimer)return;reloadTimer=window.setTimeout(()=>{reloadTimer=undefined;load()},300)}
function resetTimer(){if(timer)clearInterval(timer);if(refreshSeconds.value)timer=window.setInterval(load,refreshSeconds.value*1000)}
function connect(){const token=localStorage.getItem('access_token');if(!token||stopped)return;const protocol=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${protocol}://${location.host}/ws/v1/status/?token=${encodeURIComponent(token)}`);socket.onopen=()=>live.value=true;socket.onclose=()=>{live.value=false;if(!stopped)reconnectTimer=window.setTimeout(connect,5000)};socket.onmessage=e=>{try{if(['monitor.result','monitor.status'].includes(JSON.parse(e.data).type))scheduleLoad()}catch{live.value=false}}}
watch(refreshSeconds,resetTimer);onMounted(async()=>{stopped=false;load();connect();try{await loadSystemSettings();refreshSeconds.value=systemSettings.dashboard_refresh_seconds}catch{refreshSeconds.value=30}if(!stopped)resetTimer()});onBeforeUnmount(()=>{stopped=true;requestVersion++;if(reloadTimer)clearTimeout(reloadTimer);if(timer)clearInterval(timer);if(reconnectTimer)clearTimeout(reconnectTimer);socket?.close()})
</script>
<template>
<div class="heading"><div><h2>监控总览</h2><p>业务可用性与当前故障态势 · 更新于 {{lastUpdated||'—'}}</p></div><div class="actions"><span class="live-pill" :class="{online:live}"><i/>{{live?'实时数据已连接':'定时刷新模式'}}</span><el-select v-model="refreshSeconds" style="width:112px"><el-option label="10 秒" :value="10"/><el-option label="30 秒" :value="30"/><el-option label="1 分钟" :value="60"/><el-option label="关闭" :value="0"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div></div>
<el-alert v-if="error" :title="error" type="error" show-icon class="error"/>
<div class="hero-grid"><section class="health-card"><div><span>整体健康度</span><strong>{{healthyRate}}<em>%</em></strong><p>{{data.states?.UP||0}} 个正常，共 {{totalStates}} 个监控项</p></div><div class="ring" :style="{'--rate':healthyRate+'%'}"><b>{{(data.states?.DOWN||data.states?.DEGRADED)?'需关注':'健康'}}</b></div></section><section class="metric-card"><span>业务系统</span><strong>{{data.businesses_total||0}}</strong><p>纳入可用性监控</p></section><section class="metric-card"><span>监控任务</span><strong>{{data.monitors_total||0}}</strong><p>24h 探测 {{data.probe_stats_24h?.total||0}} 次</p></section><section class="metric-card good"><span>24h 成功率</span><strong>{{data.probe_stats_24h?.success_rate==null?'—':data.probe_stats_24h.success_rate+'%'}}</strong><p>成功 {{data.probe_stats_24h?.passed||0}} 次</p></section><section class="metric-card danger"><span>开放事件</span><strong>{{data.open_incidents||0}}</strong><p>今日新增 {{data.today_incidents||0}} 个</p></section></div>
<div class="content-grid"><el-card shadow="never"><template #header><div class="card-title"><div><b>监控状态分布</b><span>当前所有任务的最新状态</span></div><el-button link type="primary" @click="router.push('/monitors')">管理任务</el-button></div></template><div class="state-list"><div v-for="s in ['UP','DOWN','DEGRADED','MAINTENANCE','PENDING']" :key="s" class="state-row"><span><i :class="stateClass(s)"/>{{stateText[s]}}</span><b>{{data.states?.[s]||0}}</b><div><em :class="stateClass(s)" :style="{width:(totalStates?(data.states?.[s]||0)/totalStates*100:0)+'%'}"/></div></div></div></el-card><el-card shadow="never"><template #header><div class="card-title"><div><b>业务健康概览</b><span>按业务系统汇总监控状态</span></div><el-button link type="primary" @click="router.push('/businesses')">查看业务</el-button></div></template><div class="business-list"><div v-for="b in businessRows.slice(0,6)" :key="b.name" class="business-row"><div><b>{{b.name}}</b><span>{{b.total}} 个监控项 · {{fmt(b.last)}}</span></div><span class="business-status" :class="b.down?'down':b.degraded?'degraded':'up'">{{b.down?`${b.down} 个故障`:b.degraded?`${b.degraded} 个降级`:'运行正常'}}</span></div><el-empty v-if="!businessRows.length" description="暂无业务数据" :image-size="60"/></div></el-card></div>
<el-card shadow="never" class="monitor-panel"><template #header><div class="card-title"><div><b>{{attention.length?'需要关注':'实时监控状态'}}</b><span>{{attention.length?'优先显示异常和待确认的探测任务':'当前全部探测均处于正常状态'}}</span></div><el-button link type="primary" @click="router.push('/monitor-results')">查看探测结果</el-button></div></template><el-table :data="attention.length?attention:data.latest_monitors" stripe empty-text="暂无监控任务"><el-table-column prop="business" label="业务系统" min-width="160"/><el-table-column prop="name" label="探测任务" min-width="180"/><el-table-column prop="type" label="类型" width="90"/><el-table-column label="状态" width="110"><template #default="s"><span class="state-badge" :class="stateClass(s.row.status)"><i/>{{stateText[s.row.status]||s.row.status}}</span></template></el-table-column><el-table-column label="响应时间" width="125"><template #default="s">{{s.row.latency_ms==null?'—':s.row.latency_ms+' ms'}}</template></el-table-column><el-table-column label="最近探测" width="185"><template #default="s">{{fmt(s.row.last_checked_at)}}</template></el-table-column></el-table></el-card>
<el-card v-if="data.recent_incidents?.length" shadow="never" class="incident-panel"><template #header><div class="card-title"><div><b>未关闭事件</b><span>最近发生的业务故障事件</span></div><el-button link type="primary" @click="router.push('/incidents')">查看全部事件</el-button></div></template><div class="incident-list"><div v-for="i in data.recent_incidents" :key="i.id" class="incident"><span class="severity" :class="i.severity.toLowerCase()">{{i.severity}}</span><div><b>{{i.title}}</b><small>{{i.business}} · {{i.monitor}} · {{fmt(i.opened_at)}}</small></div><span>{{i.status}}</span></div></div></el-card>
</template>
<style scoped>
.heading{display:flex;justify-content:space-between;align-items:center}.heading h2{margin:0;color:#17263b}.heading p{margin:6px 0 0;color:#7d8c9e;font-size:14px}.actions{display:flex;align-items:center;gap:9px}.live-pill{display:flex;align-items:center;gap:7px;color:#7c8998;font-size:12px;padding:6px 9px;background:#f5f7fa;border:1px solid #e2e7ed;border-radius:4px}.live-pill i{width:7px;height:7px;border-radius:50%;background:#9ba7b4}.live-pill.online{color:#26764e;background:#edf8f2;border-color:#cce8d8}.live-pill.online i{background:#35a66a;box-shadow:0 0 0 3px #d8f0e2}.error{margin-top:16px}.hero-grid{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:14px;margin:20px 0}.health-card,.metric-card{background:#fff;border:1px solid #dde5ee;border-radius:8px;min-height:122px;padding:20px;box-shadow:0 2px 8px #20344c0a}.health-card{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(135deg,#0e3d64,#155b82);color:#fff;border:0}.health-card span,.metric-card span{font-size:13px}.health-card span{color:#bcd7e9}.health-card strong,.metric-card strong{display:block;font-size:29px;margin:8px 0 5px}.health-card strong em{font-size:15px;font-style:normal}.health-card p,.metric-card p{margin:0;font-size:12px}.health-card p{color:#a9c9dc}.metric-card{border-top:3px solid #3e7da9}.metric-card span,.metric-card p{color:#8290a1}.metric-card strong{color:#20334a}.metric-card.good{border-top-color:#36a66b}.metric-card.danger{border-top-color:#df5b5b}.ring{--rate:0%;width:72px;height:72px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#55d39a var(--rate),#ffffff26 0);position:relative}.ring:after{content:'';position:absolute;inset:7px;border-radius:50%;background:#144f75}.ring b{z-index:1;font-size:12px}.content-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:14px;margin-bottom:14px}.card-title{display:flex;justify-content:space-between;align-items:center}.card-title>div{display:flex;flex-direction:column}.card-title b{color:#26394f}.card-title span{color:#8b97a6;font-size:12px;margin-top:4px}.state-list{display:grid;gap:13px}.state-row{display:grid;grid-template-columns:105px 36px 1fr;align-items:center;gap:10px;font-size:13px}.state-row>span{display:flex;align-items:center;gap:8px}.state-row i,.state-badge i{width:8px;height:8px;border-radius:50%;background:#8998a8}.state-row>div{height:7px;background:#edf1f5;border-radius:5px;overflow:hidden}.state-row em{display:block;height:100%;min-width:2px;background:#8194a8}.up{background-color:#36a66b!important}.down{background-color:#df5b5b!important}.degraded{background-color:#e7a641!important}.maintenance{background-color:#4686b5!important}.pending{background-color:#9aa6b3!important}.business-row{display:flex;justify-content:space-between;align-items:center;padding:10px 2px;border-bottom:1px solid #edf0f4}.business-row>div{display:flex;flex-direction:column}.business-row b{font-size:13px;color:#2b3c51}.business-row span{font-size:11px;color:#8a97a6;margin-top:3px}.business-status{padding:5px 8px;border-radius:4px!important;margin:0!important}.business-status.up{color:#26774e;background:#eaf7f0!important}.business-status.down{color:#b54141;background:#fff0f0!important}.business-status.degraded{color:#966817;background:#fff7e8!important}.monitor-panel,.incident-panel{margin-bottom:14px}.state-badge{display:inline-flex;align-items:center;gap:7px;background:none!important;font-weight:600;font-size:13px}.state-badge.up{color:#278153}.state-badge.down{color:#c64b4b}.state-badge.degraded{color:#a16c14}.incident{display:grid;grid-template-columns:80px 1fr 110px;align-items:center;gap:12px;padding:11px 3px;border-bottom:1px solid #edf0f4}.incident>div{display:flex;flex-direction:column}.incident small{color:#8996a6;margin-top:4px}.severity{font-size:10px;font-weight:700;text-align:center;padding:4px;border-radius:4px;background:#edf1f5}.severity.critical,.severity.high{color:#b63f3f;background:#fdecec}.severity.medium{color:#966817;background:#fff4dc}@media(max-width:1250px){.hero-grid{grid-template-columns:repeat(4,1fr)}.health-card{grid-column:span 2}.content-grid{grid-template-columns:1fr}}@media(max-width:800px){.heading{align-items:flex-start}.actions .live-pill{display:none}.hero-grid{grid-template-columns:repeat(2,1fr)}.health-card{grid-column:span 2}}
</style>


